.darma-loader-darma-b15-knitting-needles { --accent: var(--loader-color, #be185d); --accent-2: var(--loader-secondary-color, #f9a8d4); width: var(--loader-size, 112px); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b15-knitting-needles .darma-loader-darma-b15-knitting-needles__pin { position: absolute; top: 8%; left: 47%; width: 6%; height: 56%; border-radius: 3px; background: linear-gradient(#f1f5f9, #94a3b8); transform-origin: 50% 92%; }
.darma-loader-darma-b15-knitting-needles .darma-loader-darma-b15-knitting-needles__pin::after { content: ''; position: absolute; left: -20%; top: -6%; width: 140%; height: 9%; border-radius: 50%; background: var(--accent); }
.darma-loader-darma-b15-knitting-needles .darma-loader-darma-b15-knitting-needles__pin:nth-of-type(1) { animation: darma-loader-darma-b15-knitting-needles-knit-left calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-darma-b15-knitting-needles .darma-loader-darma-b15-knitting-needles__pin:nth-of-type(2) { animation: darma-loader-darma-b15-knitting-needles-knit-right calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-darma-b15-knitting-needles .darma-loader-darma-b15-knitting-needles__ball { position: absolute; bottom: 3%; left: 31%; width: 38%; height: 38%; border-radius: 50%; background: repeating-conic-gradient(from 0deg, var(--accent) 0 12%, var(--accent-2) 0 24%); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 18%, transparent); animation: darma-loader-darma-b15-knitting-needles-knit-roll calc(var(--loader-speed, 1s) * 3) linear infinite; }
@keyframes darma-loader-darma-b15-knitting-needles-knit-left { 0%, 100% { transform: rotate(-28deg); } 50% { transform: rotate(-7deg); } }
@keyframes darma-loader-darma-b15-knitting-needles-knit-right { 0%, 100% { transform: rotate(28deg); } 50% { transform: rotate(7deg); } }
@keyframes darma-loader-darma-b15-knitting-needles-knit-roll { to { transform: rotate(-1turn); } }

